// Generate unique email for this run
const ts = Date.now();
const email = `ada+${ts}@example.com`;
pm.environment.set("testEmail", email);
console.log(`📧 Registering with: ${email}`);

pm.test("Status 201 Created", () => {
  pm.response.to.have.status(201);
});

const body = pm.response.json();

pm.test("Returns user object", () => {
  pm.expect(body).to.have.property("id");
  pm.expect(body).to.have.property("email");
  pm.expect(body).to.not.have.property("passwordHash");
});

console.log(`✅ User registered: ${body.email}`);

pm.test("Status 200 OK", () => {
  pm.response.to.have.status(200);
});

const body = pm.response.json();

pm.test("Returns user + tokens", () => {
  pm.expect(body).to.have.property("user");
  pm.expect(body).to.have.property("tokens");
  pm.expect(body.tokens).to.have.property("accessToken");
  pm.expect(body.tokens).to.have.property("refreshToken");
  pm.expect(body.tokens).to.have.property("expiresIn");
});

// ⭐ SAVE TOKENS — this is what makes the whole chain work
if (body.tokens && body.tokens.accessToken && body.tokens.refreshToken) {
  pm.environment.set("accessToken", body.tokens.accessToken);
  pm.environment.set("refreshToken", body.tokens.refreshToken);
  console.log("✅ Tokens saved to environment");
  console.log("accessToken length:", body.tokens.accessToken.length);
  console.log("refreshToken length:", body.tokens.refreshToken.length);
} else {
  console.error("❌ No tokens in response!");
}

pm.test("Status 200 OK", () => {
  pm.response.to.have.status(200);
});

const body = pm.response.json();

pm.test("Returns fresh tokens", () => {
  pm.expect(body).to.have.property("tokens");
  pm.expect(body.tokens.accessToken).to.be.a("string");
  pm.expect(body.tokens.refreshToken).to.be.a("string");
});

// Rotate: save new tokens
if (body.tokens && body.tokens.accessToken && body.tokens.refreshToken) {
  pm.environment.set("accessToken", body.tokens.accessToken);
  pm.environment.set("refreshToken", body.tokens.refreshToken);
  console.log("🔄 Tokens rotated successfully");
}

pm.test("Status 200 OK", () => {
  pm.response.to.have.status(200);
});

const body = pm.response.json();

pm.test("Confirms logout", () => {
  pm.expect(body).to.have.property("message");
});

console.log("✅ Logged out:", body.message);

pm.test("Status 200 OK", () => {
  pm.response.to.have.status(200);
});

const body = pm.response.json();

pm.test("Confirms all sessions revoked", () => {
  pm.expect(body).to.have.property("message");
});

// Clear tokens now — we're logged out everywhere
pm.environment.unset("accessToken");
pm.environment.unset("refreshToken");
console.log("🧹 All sessions revoked, tokens cleared");

// Runs after EVERY request in this collection
pm.test("Response time is less than 2000ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Has correlation ID header", () => {
  // Only assert if header is expected (skip on errors)
  if (pm.response.code < 500) {
    pm.expect(pm.response.headers.has("x-correlation-id")).to.be.true;
  }
});
